.info-panel { padding: 1.5rem; }
.game-info h3 { margin-bottom: 1rem; font-size: 1.1rem; color: var(--accent-light); }
.score-display { display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 1rem; }
.score-item { display: flex; align-items: center; gap: 0.5rem; font-size: 0.9rem; }
.captures { color: var(--text-muted); font-size: 0.8rem; margin-left: auto; }
.move-counter { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 1rem; }
.game-controls { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-bottom: 1rem; }
.game-controls button { flex: 1; min-width: 80px; }

/* Toggle switch */
.toggle { display: flex; align-items: center; gap: 0.5rem; cursor: pointer; font-size: 0.85rem; color: var(--text-secondary); }
.toggle input { display: none; }
.toggle-slider {
    width: 36px; height: 20px;
    background: var(--text-muted);
    border-radius: 10px;
    position: relative;
    transition: var(--transition);
}
.toggle-slider::after {
    content: '';
    width: 16px; height: 16px;
    background: white;
    border-radius: 50%;
    position: absolute;
    top: 2px; left: 2px;
    transition: var(--transition);
}
.toggle input:checked + .toggle-slider { background: var(--accent); }
.toggle input:checked + .toggle-slider::after { left: 18px; }

