let showEstimate = false;
let showWinRate = true;
let lastStatus = null;

// ---- Mode tabs -------------------------------------------------------

const humanPanels = ['setup-panel', 'game-area'];
const matchPanels = ['match-setup-panel', 'match-area'];

function el(id) {
    return document.getElementById(id);
}

function setPlayMode(mode) {
    document.querySelectorAll('.play-mode-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.playMode === mode);
    });

    // Only ever show the panel of the active half that is currently in use:
    // the setup panel before a game/match starts, the board once it has.
    const humanRunning = el('game-area') && el('game-area').dataset.started === '1';
    if (mode === 'human') {
        matchPanels.forEach(id => { if (el(id)) el(id).style.display = 'none'; });
        el('setup-panel').style.display = humanRunning ? 'none' : '';
        el('game-area').style.display = humanRunning ? 'grid' : 'none';
    } else {
        humanPanels.forEach(id => { if (el(id)) el(id).style.display = 'none'; });
        const live = !!matchId;
        el('match-setup-panel').style.display = live ? 'none' : '';
        el('match-area').style.display = live ? 'grid' : 'none';
        if (live && matchBoard) matchBoard.resize();
        if (!live) loadOpponents();
    }
}

document.querySelectorAll('.play-mode-tab').forEach(tab => {
    tab.addEventListener('click', () => setPlayMode(tab.dataset.playMode));
});

// game.js hides the setup panel itself when a game starts; mark it so the
// tabs can restore the right half without reaching into its state.
const startBtn = el('start-game');
if (startBtn) {
    startBtn.addEventListener('click', () => {
        const area = el('game-area');
        if (area) area.dataset.started = '1';
    });
}
const newGameBtn = el('btn-new-game');
if (newGameBtn) {
    newGameBtn.addEventListener('click', () => {
        const area = el('game-area');
        if (area) area.dataset.started = '';
    });
}

// ---- Opponent picker -------------------------------------------------

async function loadOpponents() {
    if (opponents) return;
    try {
        const res = await fetch('/api/match/opponents');
        opponents = await res.json();
    } catch (err) {
        showMatchError('Could not load the list of bots.');
        return;
    }
    populateSelect('match-player-a', 0);
    populateSelect('match-player-b', 1);
    syncSides();
}

/** Options: every model, the random bot, and any future (disabled) types. */
function populateSelect(selectId, defaultIndex) {
    const select = el(selectId);
    if (!select) return;
    select.innerHTML = '';

    const models = opponents.models || [];
    if (models.length) {
        const group = document.createElement('optgroup');
        group.label = 'Trained models';
        models.forEach(m => {
            const opt = document.createElement('option');
            opt.value = JSON.stringify({ type: 'model', model_id: m.model_id });
            opt.textContent = `${m.name} — ${Math.round(m.elo)} Elo (${m.kyu_rank}), ${m.board_size}×${m.board_size}`;
            opt.dataset.boardSize = m.board_size;
            opt.dataset.modelId = m.model_id;
            group.appendChild(opt);
        });

