462	        const nameA = (players.a || {}).name || 'A';
463	        const nameB = (players.b || {}).name || 'B';
464	        if (series.a === series.b) return `Tied ${series.a}–${series.b} (${nameA} vs ${nameB})`;
465	        const leader = series.a > series.b ? nameA : nameB;
466	        const high = Math.max(series.a, series.b);
467	        const low = Math.min(series.a, series.b);
