472	        if (!move) return '';
473	        if (move[0] === -1) return 'pass';
474	        if (move[0] === -2) return 'resign';
475	        // Column letters skip I, the usual Go convention.
476	        const letters = 'ABCDEFGHJKLMNOPQRST';
477	        const size = matchBoard ? matchBoard.boardSize : 9;
478	        return `${letters[move[1]] || '?'}${size - move[0]}`;
