/* ---- Play launcher ---- */
.play-launcher {
    max-width: 760px;
    margin: 2rem auto 0;
}
.play-launcher-head { text-align: center; margin-bottom: 1.5rem; }
.play-launcher-head h2 { margin-bottom: 0.35rem; }
.play-launcher-sub { color: var(--text-muted); font-size: 0.9rem; }

.play-launcher-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 1rem;
}
.play-launch-card {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.4rem;
    padding: 1.4rem;
    text-align: left;
    cursor: pointer;
    border: 1px solid var(--border-glass);
    border-radius: var(--radius);
    transition: var(--transition);
}
.play-launch-card:hover {
    border-color: var(--accent);
    transform: translateY(-2px);
}
.play-launch-icon { font-size: 1.8rem; }
.play-launch-name { font-size: 1.05rem; font-weight: 600; color: var(--text-primary); }
.play-launch-note { font-size: 0.82rem; color: var(--text-muted); line-height: 1.45; }

.play-inprogress {
    margin-top: 1.75rem;
    padding: 1rem 1.2rem;
    background: rgba(0, 0, 0, 0.2);
    border: 1px solid var(--border-glass);
    border-radius: var(--radius);
}
.play-inprogress[hidden] { display: none; }
.play-inprogress-list { display: flex; flex-direction: column; gap: 0.4rem; margin-top: 0.6rem; }
.play-inprogress-note {
    margin-top: 0.7rem;
    font-size: 0.75rem;
    color: var(--text-muted);
}
.play-progress-row {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.55rem 0.7rem;
    background: rgba(255, 255, 255, 0.03);
    border-radius: var(--radius-sm);
    font-size: 0.85rem;
}
.play-progress-dot {
    width: 8px; height: 8px;
    border-radius: 50%;
    flex: 0 0 auto;
    background: var(--text-muted);
}
.play-progress-dot.is-live {
    background: var(--success, #81c784);
    animation: playPulse 1.6s ease-in-out infinite;
}
.play-progress-dot.is-done { background: var(--text-muted); }
@keyframes playPulse {
    0%, 100% { opacity: 1; }
    50%      { opacity: 0.35; }
}
.play-progress-name {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-primary);
}
.play-progress-meta { font-size: 0.75rem; color: var(--text-muted); flex: 0 0 auto; }
.play-progress-btn { padding: 0.3rem 0.7rem; font-size: 0.78rem; flex: 0 0 auto; }
.play-progress-dismiss { flex: 0 0 auto; opacity: 0.5; }
.play-progress-dismiss:hover { opacity: 1; }

.play-back-link {
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 0.82rem;
    cursor: pointer;
    padding: 0 0 0.6rem;
    transition: var(--transition);
}
.play-back-link:hover { color: var(--accent-light); }

/* ---- End-of-series banner ---- */
.match-summary {
    margin-bottom: 1rem;
    padding: 0.9rem 1rem;
    border-radius: var(--radius-sm);
    background: rgba(200, 149, 108, 0.12);
    border: 1px solid var(--accent);
}
.match-summary[hidden] { display: none; }
.match-summary[data-outcome="stopped"],
.match-summary[data-outcome="error"] {
    background: rgba(255, 167, 38, 0.12);
    border-color: rgba(255, 167, 38, 0.5);
}
.match-summary-badge {
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--accent-light);
    margin-bottom: 0.3rem;
}
.match-summary-title {
    font-size: 1rem;
    margin: 0 0 0.35rem;
    color: var(--text-primary);
}
.match-summary-score { font-size: 0.8rem; color: var(--text-secondary); }
.match-summary-elo { font-size: 0.78rem; color: var(--text-muted); margin-top: 0.25rem; }
.match-summary-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.8rem;
}
.match-summary-actions button,
.match-summary-actions .match-summary-review {
    flex: 1 1 auto;
    padding: 0.45rem 0.8rem;
    font-size: 0.82rem;
    text-align: center;
    text-decoration: none;
    border-radius: var(--radius-sm);
}

#match-setup-panel { max-width: 620px; }

