        'board_size': board_size,
        'komi': komi,
    }

    # If player is white, bot plays first (as black)
    if player_color == 'white':
        _bot_move(game_id)
        response['state'] = game_sessions[game_id]['state'].to_dict()

    return jsonify(response)


